public class Solution {
    static class Calculadora {
        double somar(double a, double b) { return validar(a + b); }
        double subtrair(double a, double b) { return validar(a - b); }
        double multiplicar(double a, double b) { return validar(a * b); }

        double dividir(double a, double b) {
            if (b == 0) throw new ArithmeticException("divisao por zero");
            return validar(a / b);
        }

        private double validar(double valor) {
            if (!Double.isFinite(valor)) {
                throw new IllegalArgumentException("operando ou resultado invalido");
            }
            return valor;
        }
    }
}

