import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void operacoesBasicas() {
        var c = new Solution.Calculadora();
        assertEquals(7.0, c.somar(3, 4));
        assertEquals(2.5, c.dividir(10, 4));
    }

    @Test void divisaoPorZero() {
        var e = assertThrows(ArithmeticException.class,
            () -> new Solution.Calculadora().dividir(1, 0));
        assertTrue(e.getMessage().contains("zero"));
    }

    @Test void entradaInvalida() {
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.Calculadora().somar(Double.NaN, 1));
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.Calculadora().multiplicar(Double.POSITIVE_INFINITY, 0));
    }
}
